# Lambda-sensitivity analysis (Reviewer 3, major comment 5).
#
# Builds the lambda-vs-attention-entropy table from whatever oof_predictions.csv
# files already exist. Each such CSV must contain one alpha_<ROI> column per ROI.
#
#   lambda = 0.002 -> ../aer_gft_cv_outputs_split_lambda0p002/oof_predictions.csv
#                     (generated by aergft_train_lambda0p002.py + aergft_infer_lambda0p002.py)
#   lambda = 0.02  -> ../aer_gft_cv_outputs_split/oof_predictions.csv
#                     (the main paper run; already exists)
#   lambda = 0.2   -> ../aer_gft_cv_outputs_split_lambda0p2/oof_predictions.csv
#                     (generated by aergft_train_lambda0p2.py + aergft_infer_lambda0p2.py)
#
# Missing files are skipped with a note, so this script can be re-run at any time.
# Output: lambda_entropy_table.csv next to this script (new file only).

import os

import numpy as np
import pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__))
PIPELINE_DIR = os.path.dirname(HERE)
OUT_CSV = os.path.join(HERE, "lambda_entropy_table.csv")

SOURCES = [
    ("0.002", os.path.join(PIPELINE_DIR, "aer_gft_cv_outputs_split_lambda0p002", "oof_predictions.csv")),
    ("0.02",  os.path.join(PIPELINE_DIR, "aer_gft_cv_outputs_split", "oof_predictions.csv")),
    ("0.2",   os.path.join(PIPELINE_DIR, "aer_gft_cv_outputs_split_lambda0p2", "oof_predictions.csv")),
]

LN22 = float(np.log(22))


def entropy_stats(csv_path: str) -> dict:
    df = pd.read_csv(csv_path)
    alpha_cols = [c for c in df.columns if c.startswith("alpha_")]
    if len(alpha_cols) != 22:
        raise ValueError(f"{csv_path}: expected 22 alpha columns, found {len(alpha_cols)}")

    A = df[alpha_cols].to_numpy(dtype=float)
    H = -(A * np.log(A + 1e-12)).sum(axis=1)          # per-window entropy (nats)

    mean_alpha = A.mean(axis=0)
    H_pool = float(-(mean_alpha * np.log(mean_alpha + 1e-12)).sum())
    top_idx = int(np.argmax(mean_alpha))

    return {
        "n_windows": len(df),
        "H_mean": float(H.mean()),
        "H_sd": float(H.std(ddof=1)),
        "H_norm_mean": float(H.mean() / LN22),
        "H_min": float(H.min()),
        "H_max": float(H.max()),
        "H_pooled_mean_alpha": H_pool,
        "H_pooled_norm": H_pool / LN22,
        "top_roi": alpha_cols[top_idx].replace("alpha_", ""),
        "top_roi_mean_alpha": float(mean_alpha[top_idx]),
        "uniform_share": 1.0 / 22.0,
    }


def main() -> None:
    rows = []
    for lam, path in SOURCES:
        if not os.path.exists(path):
            print(f"[skip] lambda={lam}: {path} not found yet")
            continue
        stats = entropy_stats(path)
        rows.append({"lambda": lam, **stats})
        print(
            f"[ok]   lambda={lam:<6} n={stats['n_windows']:4d}  "
            f"H={stats['H_mean']:.4f}+/-{stats['H_sd']:.4f} nats "
            f"({stats['H_norm_mean']:.4f} norm)  "
            f"pooled={stats['H_pooled_norm']:.4f}  "
            f"top={stats['top_roi']} ({stats['top_roi_mean_alpha']:.4f})"
        )

    if not rows:
        print("\nNo oof_predictions.csv found yet; nothing to tabulate.")
        return

    out = pd.DataFrame(rows)
    out.to_csv(OUT_CSV, index=False, encoding="utf-8-sig")
    print(f"\n>>> Table saved to {OUT_CSV}")
    print(out.to_string(index=False))


if __name__ == "__main__":
    main()
